const embedded=window.parent!==window;
if(embedded){document.documentElement.classList.add('vendor-voice');const banner=document.createElement('div');banner.className='assistant-return';banner.innerHTML='<p>Review suggestions, apply what’s right, and return to your listing.</p><button class="primary" id="return-vendor">Done & return to my profile →</button>';document.body.prepend(banner);document.getElementById('return-vendor').onclick=async()=>{await stopVoice('Session ended');sendVendorDraft();parent.document.getElementById('assistant').close();};}
function sendVendorDraft(){const result=BubsVendorContract.selectApplied(voice.proposals,voice.draft,state.data.voiceEvidence,vendorContext.category);if(!Object.keys(result.data).length)return;parent.postMessage({type:'bubs-vendor-updates',...result},location.origin)}
window.addEventListener('message',async event=>{if(event.origin!==location.origin||event.source!==parent)return;if(event.data?.type==='bubs-vendor-context'){const category=event.data.category;if(!BubsVendorContract.categories[category])return;vendorContext={category,focus:(event.data.focus||[]).filter(key=>BubsVendorContract.keysForCategory(category).includes(key)).slice(0,8),section:String(event.data.section||'Your profile').slice(0,70)};state.type=category;state.data={...event.data.data};voice.draft={...event.data.data};state.page='voice';render();await connectVoiceGateway();}if(event.data?.type==='bubs-end-voice'){await stopVoice('Session ended');sendVendorDraft();}});
if(embedded)render();
